interface RPC {
  name: string
  generate(context: RPCContext): Artifact[]
}

interface RPCContext {
  ipc: string
  rpc: string
  module: 'esm' | 'cjs'
  role: 'client' | 'server'
}

interface RPCClient {
  source: string
  type: string
}

interface Artifact {
  extension?: string
  source: string
